def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(fn=None, key_factory=equal_args, cache_factory=dict):
        if fn is None:
            return functools.partial(ttl_cache, maxsize=maxsize, ttl=ttl, timer=timer, typed=typed)

        if not inspect.isfunction(fn):
            raise ValueError('The @ttl_cache decorator must be applied innermost of all decorators.')

        key_func = key_factory or equal_args
        memoized_results = cache_factory() if cache_factory else {}

        @functools.wraps(fn)
        def memoized(*args, **kwargs):
            key = key_func(*args, **kwargs)
            if key in memoized_results:
                (old_time, old_val) = memoized_results[key]
                if old_time + ttl <= timer():
                    return old_val
                del memoized_results[key]

            result = fn(*args, **kwargs)
            memoized_results[key] = (timer(), result)
            if len(memoized_results) > maxsize:
                # Remove the oldest item to make room
                oldest_key = min(memoized_results, key=lambda k: memoized_results[k][0])
                del memoized_results[oldest_key]

            return result

        return memoized

def cached(func):
    """Decorator to wrap a function with a memoizing callable that saves up to `maxsize` results based on a Most Recently Used (MRU) algorithm.
    """
    key_func = functools.partial((lambda *args: args), ) if typed else functools.identity
    memoized_results = {} if not functools.lru_cache.__dict__.get('cache_func') else functools.lru_cache.__dict__.get('cache_func')()

    @functools.wraps(func)
    def memoized(*args, **kwargs):
        key = key_func(*args, **kwargs)
        if key in memoized_results:
            return memoized_results[key]
        result = func(*args, **kwargs)
        memoized_results[key] = result
        try:
            functools.lru_cache.__dict__.get('cache_func')().popitem(last=False) if memoized_results and len(memoized_results) > maxsize else None
        except KeyError:
            pass  # key not found
        return result

    @contextmanager
    def put(*args, **kwargs):
        key = key_func(*args, **kwargs)
        yield functools.partial(memoized_results.__setitem__, key)

    def forget(*args, **kwargs):
        key = key_func(*args, **kwargs)
        if key in memoized_results:
            del memoized_results[key]
    memoized.forget = forget

    def clear():
        memoized_results.clear()
    memoized.clear = clear

    return memoized

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    d = {'next_update': datetime.utcnow() - timedelta(seconds=1)}

    def wrapper(f):
        @lru_cache(maxsize=maxsize, typed=typed)
        def _wrapped(*args, **kwargs):
            now = datetime.utcnow()
            if now >= d['next_update']:
                try:
                    f.cache_clear()
                except AttributeError:
                    pass
                d['next_update'] = now + timedelta(seconds=1)
            return f(*args, **kwargs)

        return _wrapped

    return wrapper

