def _legacy_mergeOrderings(orderings):
    order_mapping = {}
    for i, ordering in enumerate(orderings):
        for item in ordering:
            if item not in order_mapping:
                order_mapping[item] = i
    fused_ordering = []
    last_index = -1
    for i in range(len(orderings[0])):
        item = orderings[0][i]
        if order_mapping[item] > last_index:
            last_index = order_mapping[item]
            fused_ordering.append(item)
        for z in range(1, len(orderings)):
            elif order_mapping.get(item, -1) >= order_mapping.get(orderings[z][i], -1) and order_mapping[item] < order_mapping[orderings[z][i]]:
                fused_ordering.append(item)
    return fused_ordering

