def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if inventory is None:
        raise ValueError("Inventory cannot be None")

    if extract_spec_version:
        type_value = inventory.get('type')
        if not type_value:
            raise ValueError("Inventory includes a 'type' field, but it's empty.")
        if type_value not in self.spec_version:
            raise ValueError("Spec version specified in inventory is not valid.")
    else:
        version = inventory.get('type', self.spec_version)

    # further validation based on the version-specific logic
    if version == 'version1':
        self._validate_version1(inventory)
    elif version == 'version2':
        self._validate_version2(inventory)
    else:
        raise ValueError("Unsupported version: {}".format(version))

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError('prior must be an InventoryValidator object')

    if self.id != prior.id:
        raise ValueError('prior inventory id does not match the current inventory id')

    if self.name != prior.name:
        raise ValueError('prior inventory name does not match the current inventory name')

    if self.species != prior.species:
        raise ValueError('prior inventory species do not match the current inventory species')

