def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    result = ""
    if padding is not None:
        result = str(number).zfill(padding)
    else:
        while number > 0:
            result = alphabet[number % len(alphabet)] + result
            number //= len(alphabet)
    return result

def subclasses(cls):

    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for c in sc:
            if c not in seen:
                queue.add(c)

    seen.remove(cls)
    return seen

