def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    output = []
    messages = []
    errors = []

    for command in commands:
        process = subprocess.Popen([command] + args, 
                                      cwd=cwd, 
                                      shell=False, 
                                      env=env, 
                                      universal_newlines=True)
        try:
            output.extend(process.communicate()[0].splitlines())
            if verbose:
                messages.append(f"Command '{command}' output: {''.join(process.communicate()[0])}")
        except subprocess.CalledProcessError as e:
            errors.append(f"Command '{command}' failed: {e.stderr.decode('utf-8')}")

    if hide_stderr:
        stderr = b""
    else:
        stderr = b"".join(errors)

    return output, messages, errors, stderr.decode('utf-8')

