def fetch_content_type(url: str) -> Optional[str]:
    """
        Fetch the HEAD of the remote url to determine the content type.

        :param url: The URL to fetch the HEAD request from.
        :return: The content type if successful, otherwise None.
        """

    req = urllib.request.Urlretrieve(url)
    try:
        resp = urllib.request.urlopen(req)
        try:
            if hasattr(resp, 'code') and resp.code != 200:
                return None
            return resp.info().get('content-type', '')
        finally:
            resp.close()
    except Exception as e:
        print(f"Error fetching content type for URL {url}: {e}")
        return None

