def parse_diaspora_webfinger(document: str) -> Optional[Dict]:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html

    :param document: JSON or XRD document as a string.
    :return: Dictionary with parsed social media details or None on error.
    """
    try:
        return json.loads(document)
    except json.JSONDecodeError:
        try:
            document = re.sub(
                r'<(?P<url>[^>]+) HTTP/', '', document
            )
            uri = urllib.parse.urlparse(document).path
            document = urllib.request.urlopen(uri).read().decode('utf-8')
            return parse_diaspora_webfinger(document)
        except Exception as e:
            logger.error("parse_diaspora_webfinger: failed to parse document: %s", str(e))
            return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.

    :arg handle: The remote handle to retrieve
    :returns: The RFC7033 webfinger document as a string, or None if retrieval fails
    """
    try:
        host = handle.split("@")[1]
        document, code, exception = fetch_document(
            host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
        )
        if document:
            return document.decode('utf-8')  # Assuming the document is encoded in UTF-8
    except HTTPException as e:
        return None
    return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

