            raise Exception("错误：缺少必需的字段：{}".format(", ".join([f"（{field}）" for field in ve.context if not field.isdigit()])))

        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """

    def resolve_include(include_dict, values):
        for key, value in iteritems(include_dict):
            if isinstance(value, dict):
                value = resolve_include(value, values)
            if key in values:
                include_dict[key] = values[key]
            elif key == 'ALL':
                include_dict = {k: v for k, v in iteritems(values) if k not in included_tracking and v}
        return include_dict

    # Resolved include dict
    resolved_include_dict = resolve_include(parser_dict['includes'], self.values)

    # Store resolved includes for later reference
    included_tracking.update(resolved_include_dict)

    # Include nested includes
    for include_key, include_dict in iteritems(resolved_include_dict):
        if 'ALL' in included_tracking:
            continue
        parser_dict = resolve_include(include_dict, self.values)
        included_tracking.update(parser_dict)

    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    spec_defaults = self._default_spec.get()
    other_sources = self._other_sources  # Assuming this is a valid attribute

    # A dictionary to hold the final defaults
    final_defaults = {}

    # Merge spec defaults with other sources
    for key in spec_defaults:
        final_defaults[key] = spec_defaults[key]

    for key in other_sources:
        final_defaults[key] = other_sources[key]

    return final_defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    deprecated_arg_names = {
        'arg1': 'new_arg1',
        'arg2': 'new_arg2'
    }

    cli_dec_args = deprecated_arg_names.keys()
    ans_dec_args = answer_file_args.keys()

    cli_missing_args = set(cli_dec_args).difference(cli_dec_args.intersection(ans_dec_args))
    ans_missing_args = set(ans_dec_args).difference(cli_dec_args.intersection(ans_dec_args))

    if cli_missing_args:
        print("Deprecated cli arguments ({}):\n".format(list(cli_missing_args)))
        for arg in cli_missing_args:
            print(f"  - {arg}")

    if ans_missing_args:
        print("Deprecated answer file arguments ({}):\n".format(list(ans_missing_args)))
        for arg in ans_missing_args:
            print(f"  - {arg}")

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silencer_list = []
    for name, value in args.items():
        if name.startswith('SILENCE_'):
            silencer_list.append(name)
    return silencer_list

def validate_requires_args(self, args):
    # Check if all the required arguments have been provided.
    required_args = ['param1', 'param2', 'param3']  # List of required arguments
    for arg in required_args:
        if arg not in args:
            raise ValueError(f"Required argument '{arg}' not provided.")

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    max_length = self.parsed_yaml.get('max_length', None)
    if max_length is None:
        return True

    for arg_name, arg_value in args.items():
        if arg_value is not None and len(arg_value) > max_length:
            abort("Argument '{}' is too long (length: {})".format(arg_name, len(arg_value)))

    return True

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        extra_vars = {}

    for key, value in extra_vars.items():
        if key in vars_dict:
            vars_dict[key] += value
        else:
            vars_dict[key] = value

def _convert_non_cli_args(self, parser_name, values_dict):
    for arg in self.cli_args:
        if arg.name in values_dict:
            values_dict[arg.name] = arg.convert(values_dict[arg.name])

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    spec = {}

    for filename in os.listdir(plugin_dir):
        file_path = os.path.join(plugin_dir, filename)
        if os.path.isfile(file_path):
            with open(file_path, 'r') as f:
                lines = f.readlines()
                plugin_info = {}
                for line in lines:
                    key, value = line.strip().split(':')
                    plugin_info[key.strip()] = value.strip()

                spec[filename] = plugin_info

    return spec

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    config_path = os.getenv('CONFIG_PATH', None)
    if config_path:
        os.environ['CONFIG_PATH'] = config_path
